// Node.js Express Backend fixing a CORS error

const cors = require('cors');

// ❌ BAD: Allows literally any website in the world to hit your API
app.use(cors({ origin: '*' }));

// ✅ GOOD: Only allows your specific frontend React app to hit the API
app.use(cors({
  origin: 'https://my-react-app.vercel.app',
  methods: ['GET', 'POST'],
  credentials: true // Required if you are sending secure cookies!
}));
